namespace Game_Catalog.Models
{
    /// <summary> Represents a gaming platform from the reference table. </summary>
    public class Platform
    {
        /// <summary> Unique identifier of the platform. Generated by the database. </summary>
        public int PlatformId { get; set; }

        private string _platformName = string.Empty;
        /// <summary> Name of the platform. </summary>
        public string PlatformName
        {
            get => _platformName;
            set => _platformName = value ?? string.Empty;
        }

        private string _manufacturer = string.Empty;
        /// <summary> Manufacturer of the platform. Empty means unknown. </summary>
        public string Manufacturer
        {
            get => _manufacturer;
            set => _manufacturer = value ?? string.Empty;
        }

        private string _platformIconPath = string.Empty;
        /// <summary> Local file path to the platform icon. Empty means no icon. </summary>
        public string PlatformIconPath
        {
            get => _platformIconPath;
            set => _platformIconPath = value ?? string.Empty;
        }
    }
}